package scenario

import "context"

// Extension hooks a subsystem (voice, evaluators, red teaming, …) into a
// scenario run without the core importing it. An extension implements Key
// plus any of the optional hook interfaces below; the executor type-asserts
// each hook. Extensions come from ScenarioConfig.Extensions and from agents
// implementing ExtensionProvider, deduplicated by Key (first wins).
type Extension interface {
	// Key identifies the extension; it also keys ScenarioResult.Extensions.
	Key() string
}

// ExtensionProvider is implemented by agents that bring an extension, for
// example a voice agent adapter bringing the voice runtime.
type ExtensionProvider interface {
	Extension() Extension
}

// RunStarter is called once before the first script step. An error fails
// the run.
type RunStarter interface {
	Start(ctx context.Context, ex *Executor) error
}

// RunStopper is called once after the run finished, on every exit path,
// after the run finished event was emitted.
type RunStopper interface {
	Stop(ctx context.Context, ex *Executor)
}

// UserTurnTransformer rewrites a user turn before it is recorded: a scripted
// text turn (producer nil) or the messages a user simulator generated. Voice
// uses it to synthesize audio.
type UserTurnTransformer interface {
	TransformUserTurn(ctx context.Context, ex *Executor, producer AgentAdapter, messages []Message) ([]Message, error)
}

// UserTurnInterceptor may take over a scripted user turn (after
// transformation). When it reports handled, the extension delivered and
// recorded the turn itself (with Executor.AddMessage) and the default path is
// skipped. Voice uses it for barge-in while an agent turn is in flight.
type UserTurnInterceptor interface {
	InterceptUserTurn(ctx context.Context, ex *Executor, message Message) (handled bool, err error)
}

// GeneratedUserTurnHook observes a user turn generated by a user simulator
// after it was recorded.
type GeneratedUserTurnHook interface {
	AfterGeneratedUserTurn(ctx context.Context, ex *Executor, message Message) error
}

// BeforeProceedStepHook runs before each agent interaction of Proceed. It
// may schedule a non-blocking agent turn with
// Executor.ScheduleAgentTurnNonBlocking.
type BeforeProceedStepHook interface {
	BeforeProceedStep(ctx context.Context, ex *Executor) error
}

// AfterProceedStepHook runs after each agent interaction of Proceed, after
// the OnStep callback, unless the scenario already concluded.
type AfterProceedStepHook interface {
	AfterProceedStep(ctx context.Context, ex *Executor) error
}

// ResultFinalizer amends the result on every exit path (verdict, failure,
// max turns, error) before the run finished event is emitted. Voice attaches
// the recording here with ScenarioResult.SetExtension.
type ResultFinalizer interface {
	FinalizeResult(ctx context.Context, ex *Executor, result *ScenarioResult) error
}

// JudgeInputOptions tell a JudgeInputPreprocessor what the judge wants.
type JudgeInputOptions struct {
	// IncludeAudio keeps audio parts next to their transcripts.
	IncludeAudio bool
}

// JudgeInputPreprocessor prepares the conversation for the judge when it
// carries audio, for example by transcribing audio parts.
type JudgeInputPreprocessor interface {
	PreprocessJudgeInput(ctx context.Context, ex *Executor, messages []Message, opts JudgeInputOptions) ([]Message, error)
}

// UserSimulatorInputPreprocessor prepares the conversation for the user
// simulator when an audio turn carries no transcript.
type UserSimulatorInputPreprocessor interface {
	PreprocessUserSimulatorInput(ctx context.Context, ex *Executor, messages []Message) ([]Message, error)
}

// JudgeContextProvider adds context to the judge's evaluation input, such as
// a voice timeline. Empty strings are ignored.
type JudgeContextProvider interface {
	JudgeContext(ctx context.Context, ex *Executor) string
}

// JudgePhase is the phase of a judge call.
type JudgePhase string

// Judge phases.
const (
	JudgePhaseDecision JudgePhase = "decision"
	JudgePhaseVerdict  JudgePhase = "verdict"
)

// JudgeTool is a non-terminal tool the judge may call during a phase; its
// result is fed back to the judge before it decides.
type JudgeTool struct {
	Definition ToolDefinition
	// Execute runs the tool with its JSON arguments.
	Execute func(ctx context.Context, arguments string) (string, error)
}

// JudgeToolProvider contributes judge tools for a phase.
type JudgeToolProvider interface {
	JudgeTools(ctx context.Context, ex *Executor, phase JudgePhase) []JudgeTool
}

// hooks holds the extensions of a run, split by hook interface once.
type hooks struct {
	all           []Extension
	starters      []RunStarter
	stoppers      []RunStopper
	transformers  []UserTurnTransformer
	interceptors  []UserTurnInterceptor
	generatedUser []GeneratedUserTurnHook
	beforeProceed []BeforeProceedStepHook
	afterProceed  []AfterProceedStepHook
	finalizers    []ResultFinalizer
	judgeInput    []JudgeInputPreprocessor
	userSimInput  []UserSimulatorInputPreprocessor
	judgeContext  []JudgeContextProvider
	judgeTools    []JudgeToolProvider
}

func collectHooks(cfg ScenarioConfig) hooks {
	var h hooks
	seen := map[string]bool{}
	add := func(e Extension) {
		if e == nil || seen[e.Key()] {
			return
		}
		seen[e.Key()] = true
		h.all = append(h.all, e)
		if v, ok := e.(RunStarter); ok {
			h.starters = append(h.starters, v)
		}
		if v, ok := e.(RunStopper); ok {
			h.stoppers = append(h.stoppers, v)
		}
		if v, ok := e.(UserTurnTransformer); ok {
			h.transformers = append(h.transformers, v)
		}
		if v, ok := e.(UserTurnInterceptor); ok {
			h.interceptors = append(h.interceptors, v)
		}
		if v, ok := e.(GeneratedUserTurnHook); ok {
			h.generatedUser = append(h.generatedUser, v)
		}
		if v, ok := e.(BeforeProceedStepHook); ok {
			h.beforeProceed = append(h.beforeProceed, v)
		}
		if v, ok := e.(AfterProceedStepHook); ok {
			h.afterProceed = append(h.afterProceed, v)
		}
		if v, ok := e.(ResultFinalizer); ok {
			h.finalizers = append(h.finalizers, v)
		}
		if v, ok := e.(JudgeInputPreprocessor); ok {
			h.judgeInput = append(h.judgeInput, v)
		}
		if v, ok := e.(UserSimulatorInputPreprocessor); ok {
			h.userSimInput = append(h.userSimInput, v)
		}
		if v, ok := e.(JudgeContextProvider); ok {
			h.judgeContext = append(h.judgeContext, v)
		}
		if v, ok := e.(JudgeToolProvider); ok {
			h.judgeTools = append(h.judgeTools, v)
		}
	}
	for _, e := range cfg.Extensions {
		add(e)
	}
	for _, a := range cfg.Agents {
		if p, ok := a.(ExtensionProvider); ok {
			add(p.Extension())
		}
	}
	return h
}
